// OMEGA-CLAW — the read-only panels (docs/omega-claw.md). SmartCiti.X Holodeck · Powered by AGI Corp.
//
// ocMountClaw(el, { record, human }) : the Omega Claw panel. The five software agents, the declarations, the runs and a
// leaderboard per scenario, the promotions and every refusal with its reason, the hash chain re-walked on this device,
// and where people and robots each need practice. Read-only: nothing here runs a comparison, approves or sends anything.
// `record` is OC_RECORD (shared/oc-claw-record.js, generated by tools/claw_eval.mjs from the declared protocol's one run).
// `human` is this device's own drill and tutor results, passed only when DATAWORKS' gate allows (opted-in adults; never
// K-12, demo or signed out); otherwise null and no learner value is read or shown.
//
// ocMountWorld(el, { loop }) : "Robots at work", the persistent world loop's view (oc-world.js): the simulated clock,
// running or paused (the tab hidden), each robot site's jobs and the model it runs, the governor's step count and the
// physical dispatches (0). One control: Pause / Resume (44 px).
//
// Every top-level name starts with `oc`/`OC_` (the bundler shares one scope).

import { ocVerifyChain, ocVerifyHead, ocPracticeNeeds, ocSideBySide, OC_AGENT_LABEL, OC_FEATURE, OC_REFUSALS } from "./oc-claw.js";

export const OC_PANEL_CSS = `
.oc-panel{font:14px/1.4 system-ui,Arial,sans-serif;color:#dbe7ee;background:rgba(8,14,22,.92);border:1px solid rgba(124,196,255,.35);border-radius:10px;padding:12px;margin:10px 0;max-width:100%;box-sizing:border-box;overflow-wrap:anywhere}
.oc-panel h3{margin:0 0 6px;font-size:16px}.oc-panel h4{margin:10px 0 4px;font-size:14px;color:#9fd3ff}
.oc-note{font-size:12px;color:#a9bccb;margin:4px 0}
.oc-roster{display:flex;flex-wrap:wrap;gap:6px}.oc-card{display:flex;gap:6px;align-items:flex-start;background:rgba(255,255,255,.04);border-radius:8px;padding:6px 8px;flex:1 1 170px;min-width:0}
.oc-glyph{width:28px;height:28px;border-radius:6px;display:grid;place-items:center;font-size:16px;color:#08101a;flex:none}
.oc-name{font-weight:700}.oc-label{display:inline-block;margin-left:6px;font-size:11px;font-weight:600;padding:1px 6px;border-radius:999px;border:1px solid #7cc4ff;color:#7cc4ff}
.oc-role{font-size:12px;color:#b8c8d4}
.oc-sum{display:flex;flex-wrap:wrap;gap:6px;margin:8px 0}.oc-stat{background:rgba(124,196,255,.1);border-radius:6px;padding:4px 8px;font-size:12px}
.oc-panel select,.oc-panel button{min-height:44px;min-width:44px;font:inherit;color:#e8f3fa;background:#13283a;border:1px solid #4fa7e0;border-radius:8px;padding:0 12px}
.oc-panel button:focus-visible,.oc-panel select:focus-visible{outline:2px solid #4fd1ff;outline-offset:2px}
.oc-board{width:100%;border-collapse:collapse;font-size:12px}.oc-board th,.oc-board td{text-align:left;padding:3px 4px;border-bottom:1px solid rgba(255,255,255,.07);vertical-align:middle}
.oc-bar{position:relative;height:10px;background:rgba(255,255,255,.08);border-radius:5px;min-width:60px}.oc-bar i{position:absolute;top:0;bottom:0;left:0;background:#7cc4ff;border-radius:5px}.oc-bar b{position:absolute;top:-2px;bottom:-2px;border-left:2px solid #ffd166;border-right:2px solid #ffd166}
.oc-v{font-size:11px;padding:1px 6px;border-radius:999px;background:rgba(255,159,128,.15);color:#ffb59e;white-space:nowrap}.oc-v[data-v=clear]{background:rgba(155,227,122,.15);color:#b6f09a}.oc-v[data-v=incumbent],.oc-v[data-v=context]{background:rgba(255,255,255,.08);color:#c9d6df}
.oc-ref{margin:3px 0;font-size:12px}.oc-ref b{color:#ffb59e}
.oc-sites{display:grid;grid-template-columns:repeat(auto-fill,minmax(160px,1fr));gap:6px}.oc-site{background:rgba(255,255,255,.04);border-radius:8px;padding:6px 8px;font-size:12px}
.oc-row{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:6px 0}
.oc-ok{color:#b6f09a}.oc-bad{color:#ff8a80}
`;

function ocMk(tag, cls, text) { const n = document.createElement(tag); if (cls) n.className = cls; if (text != null) n.textContent = text; return n; }
function ocStyleOnce(box) { const s = document.createElement("style"); s.textContent = OC_PANEL_CSS; box.appendChild(s); }

/** The verdict a model's row shows in a scenario's leaderboard. */
export function ocRowVerdict(record, run, modelId) {
  const d = record.declarations.find((x) => x.id === run.declId);
  if (!d) return "context";
  if (modelId === d.incumbent) return "incumbent";
  const v = record.comparisons.find((c) => c.declId === run.declId && c.challenger === modelId);
  return v ? v.verdict : "context";
}

export function ocMountClaw(el, { record = null, records = null, human = null, onSelect = null } = {}) {
  const recs = (Array.isArray(records) && records.length ? records : [record]).filter(Boolean);
  record = record ?? recs[recs.length - 1];
  if (!el || typeof document === "undefined" || !record) return null;
  const box = ocMk("section", "oc-panel"); box.id = "oc-claw"; box.setAttribute("aria-label", `${OC_FEATURE}: the software agents that run robot training and model testing`);
  ocStyleOnce(box);
  box.appendChild(ocMk("h3", null, `${OC_FEATURE} — robot training and model testing`));
  box.appendChild(ocMk("p", "oc-note", "Five software agents (invented names; no language model, no network call) declare each comparison before it runs, run ROBO-ARENA's simulated robots once on held-out seeds, check for leakage and seed reuse, and promote a model only with a clear, rule-clean win the governor watched step by step. Read-only; robots are simulated."));

  const roster = ocMk("div", "oc-roster"); roster.setAttribute("role", "list");
  for (const a of record.agents) {
    const c = ocMk("div", "oc-card"); c.setAttribute("role", "listitem"); c.dataset.agent = a.id;
    const g = ocMk("div", "oc-glyph", a.avatar?.glyph ?? "◇"); g.style.background = a.avatar?.accent ?? "#7cc4ff"; g.setAttribute("aria-hidden", "true");
    const b = ocMk("div"); const n = ocMk("div", "oc-name", a.name); n.appendChild(ocMk("span", "oc-label", OC_AGENT_LABEL)); b.append(n, ocMk("div", "oc-role", a.role));
    c.append(g, b); roster.appendChild(c);
  }
  box.appendChild(roster);

  // One protocol at a time (a select when there are several); everything below re-renders for it.
  let sel = null, chain = null, need = null;
  if (recs.length > 1) {
    const prow = ocMk("div", "oc-row");
    const plab = ocMk("label", null, "Protocol "); plab.htmlFor = "oc-protocol";
    const psel = ocMk("select"); psel.id = "oc-protocol"; psel.dataset.oc = "protocol";
    recs.forEach((r, i) => { const o = ocMk("option", null, `${r.protocol.version} · seeds ${r.protocol.seeds}`); o.value = String(i); if (r === record) o.selected = true; psel.appendChild(o); });
    psel.addEventListener("change", () => { record = recs[Number(psel.value)] ?? record; renderBody(); });
    prow.append(plab, psel); box.appendChild(prow);
  }
  const body = ocMk("div"); body.dataset.oc = "body"; box.appendChild(body);
  function renderBody() {
  body.textContent = "";
  chain = record.chainHead ? { ...ocVerifyHead(record.chainHead, record.chainTail), head: true } : { ...ocVerifyChain(record.chain ?? []), head: false };
  const k = record.counts;
  const ex = Object.values(k.exercised ?? {}).filter(Boolean).length;
  const sum = ocMk("div", "oc-sum");
  const stat = (t, key) => { const s = ocMk("span", "oc-stat", t); if (key) s.dataset.oc = key; sum.appendChild(s); return s; };
  stat(`Declared comparisons: ${k.declaredComparisons}, run once: ${k.comparisonsRunOnce}`, "declared");
  stat(`Held-out seeds ${record.protocol.seeds}`, "seeds");
  stat(`Promotions: ${k.promotions} (clear: ${k.promotionsClear}/${k.promotions})`, "promotions");
  stat(`Refusals exercised: ${ex}/3`, "exercised");
  stat(`Governor: ${k.stepsChecked.toLocaleString("en-US")}/${k.stepsRun.toLocaleString("en-US")} steps · physical ${k.physical}`, "governor");
  const cs = stat(chain.head ? `Audit chain head ${String(chain.hash).slice(0, 8)}: ${chain.ok ? "matches" : "does not match"} its last line, re-hashed on this device (${chain.lines} lines; the full chain is re-walked by check_claw from the committed record)` : `Audit chain: ${chain.ok ? "intact" : `broken at line ${chain.brokenAt}`} (${chain.lines} lines, re-walked on this device)`, "chain"); cs.classList.add(chain.ok ? "oc-ok" : "oc-bad");
  body.appendChild(sum);

  // Declarations
  body.appendChild(ocMk("h4", null, "Declarations (committed before the run)"));
  const probesDeclared = record.declarations.filter((d) => /^oc-probe-/.test(d.id)).length;
  const dl = ocMk("p", "oc-note", `${record.declarations.length - probesDeclared} declarations, one per scenario${probesDeclared ? ` (plus ${probesDeclared} probe declared only to be refused)` : ""}: ${record.protocol.models.length} models each, incumbent ${record.protocol.incumbent}, challengers ${record.protocol.challengers.join(", ")} (${record.protocol.negativeControl} is a declared negative control). Metric: ${record.protocol.metric}; ${record.protocol.interval}. Promotion: ${record.protocol.promotion}.`);
  dl.dataset.oc = "declarations"; body.appendChild(dl);

  // Leaderboard per scenario
  body.appendChild(ocMk("h4", null, "Runs and leaderboard"));
  const row = ocMk("div", "oc-row");
  const lab = ocMk("label", null, "Scenario "); lab.htmlFor = "oc-scenario";
  sel = ocMk("select"); sel.id = "oc-scenario"; sel.dataset.oc = "scenario";
  for (const r of record.runs) { const o = ocMk("option", null, r.scenarioId); o.value = r.declId; sel.appendChild(o); }
  row.append(lab, sel); body.appendChild(row);
  const tbl = ocMk("table", "oc-board"); tbl.dataset.oc = "board"; body.appendChild(tbl);
  function draw(declId) {
    const run = record.runs.find((r) => r.declId === declId) ?? record.runs[0];
    const d = record.declarations.find((x) => x.id === run.declId);
    tbl.innerHTML = "";
    const cap = ocMk("caption", "oc-note", `${run.scenarioId}: ${d?.seeds ?? run.seeds} held-out seeds ${d?.seedRange ?? ""}, declaration ${String(d?.hash ?? "").slice(0, 8)}`); tbl.appendChild(cap);
    const hr = ocMk("tr"); for (const h of ["#", "Model", "Success", "95% interval", "Rule breaks", "Verdict"]) hr.appendChild(ocMk("th", null, h)); tbl.appendChild(hr);
    const rows = run.results.filter((x) => x.applicable).sort((a, b) => b.rate - a.rate || a.ruleBreaks - b.ruleBreaks || (a.modelId < b.modelId ? -1 : 1));
    rows.forEach((x, i) => {
      const tr = ocMk("tr"); tr.dataset.model = x.modelId;
      const bar = ocMk("div", "oc-bar"); const fill = ocMk("i"); fill.style.width = `${Math.round(x.rate * 100)}%`; const ci = ocMk("b"); ci.style.left = `${x.ci[0] * 100}%`; ci.style.width = `${Math.max(0, (x.ci[1] - x.ci[0]) * 100)}%`; bar.append(fill, ci);
      const sc = ocMk("td"); sc.append(ocMk("div", null, `${x.k}/${x.n}`), bar);
      const v = ocRowVerdict(record, run, x.modelId); const vs = ocMk("span", "oc-v", v === "clear" ? "promoted" : v); vs.dataset.v = v; vs.title = OC_REFUSALS[v] ?? "";
      const vt = ocMk("td"); vt.appendChild(vs);
      tr.append(ocMk("td", null, String(i + 1)), ocMk("td", null, x.modelId), sc, ocMk("td", null, `${x.ci[0]}–${x.ci[1]}`), ocMk("td", null, String(x.ruleBreaks)), vt);
      tbl.appendChild(tr);
    });
    const na = run.results.filter((x) => !x.applicable).map((x) => x.modelId);
    if (na.length) { const tr = ocMk("tr"); const td = ocMk("td", "oc-note", `Not applicable here: ${na.join(", ")}`); td.colSpan = 6; tr.appendChild(td); tbl.appendChild(tr); }
    try { onSelect?.(run.declId); } catch (_) { /* a view hook never breaks the panel */ }
  }
  sel.addEventListener("change", () => draw(sel.value));
  draw(record.runs[0]?.declId);

  // Promotions
  body.appendChild(ocMk("h4", null, "Promotions"));
  const pr = ocMk("div"); pr.dataset.oc = "promotions";
  if (!record.promotions.length) pr.appendChild(ocMk("p", "oc-note", `None this round: no challenger cleared the gate in ${k.declaredComparisons} declared comparisons, so the incumbent (${record.protocol.incumbent}) keeps every scenario.`));
  for (const p of record.promotions) pr.appendChild(ocMk("p", "oc-ref", `${p.scenarioId}: ${p.from} → ${p.to} (interval ${p.cCi.join("–")} against ${p.iCi.join("–")}, 0 rule breaks, governor ${p.governorChecked}/${p.steps} steps)`));
  body.appendChild(pr);

  // Refusals
  body.appendChild(ocMk("h4", null, "Refusals, with reasons"));
  const rf = ocMk("div"); rf.dataset.oc = "refusals";
  const byReason = new Map(); for (const r of record.refusals) { if (!byReason.has(r.reason)) byReason.set(r.reason, []); byReason.get(r.reason).push(r); }
  const order = ["undeclared", "seed-reused", "rule-broken", "interval-overlap", "not-better", "not-applicable"];
  for (const reason of [...order.filter((r) => byReason.has(r)), ...[...byReason.keys()].filter((r) => !order.includes(r))]) {
    const xs = byReason.get(reason);
    // The telling example: a rule-broken challenger whose interval was otherwise clear of the incumbent's, then any learner, then the first.
    const cleared = (r) => record.comparisons.some((c) => c.declId === r.declId && c.challenger === r.challenger && c.cCi && c.iCi && c.cCi[0] > c.iCi[1]);
    const ex1 = xs.find((r) => r.reason === "rule-broken" && !r.negativeControl && cleared(r)) ?? xs.find((r) => !r.negativeControl) ?? xs[0];
    const p = ocMk("p", "oc-ref"); p.dataset.reason = reason;
    p.append(ocMk("b", null, `${reason} × ${xs.length}`), document.createTextNode(` — ${OC_REFUSALS[reason] ?? reason}. e.g. ${ex1.name ?? ex1.agent}: ${ex1.subject}${ex1.ruleBreaks ? ` (${ex1.ruleBreaks} rule breaks${cleared(ex1) ? ", though its interval was clear of the incumbent's" : ""})` : ""}.`));
    rf.appendChild(p);
  }
  body.appendChild(rf);

  // People and robots
  body.appendChild(ocMk("h4", null, "Where people and robots each need practice"));
  need = ocPracticeNeeds({ runs: record.runs, promoted: record.promoted, human });
  const pp = ocMk("div"); pp.dataset.oc = "practice"; pp.dataset.learner = need.learnerData;
  pp.appendChild(ocMk("p", "oc-note", `Robots (the model each scenario runs): ${need.robots.length ? need.robots.map((r) => `${r.scenarioId} — ${r.modelId}, ${r.why}`).join("; ") : "none below the mark"}.`));
  pp.appendChild(ocMk("p", "oc-note", human?.eligible ? `People (this device's own drills and tutor, never sent anywhere): ${need.people.length ? need.people.map((p) => `${p.kind === "drill" ? "drill" : "cell-entry step"} ${p.id} — ${p.why}`).join("; ") : "nothing below the mark yet"}.` : "People: your own drill and tutor results show here once you have opted in on this device (adults only; never in K-12, demo or signed-out sessions). Nothing is read until then."));
  body.appendChild(pp);


  // People and robots side by side, per scenario
  body.appendChild(ocMk("h4", null, "Side by side: each robot scenario and its learner stations"));
  const sbs = ocSideBySide({ runs: record.runs, promoted: record.promoted, human });
  const st = ocMk("table", "oc-board"); st.dataset.oc = "side"; st.dataset.learner = human?.eligible ? "local" : "none";
  const sh = ocMk("tr"); for (const h of ["Scenario", "Robot (model, success, gap)", "People (matching stations, gap)"]) sh.appendChild(ocMk("th", null, h)); st.appendChild(sh);
  for (const x of sbs) {
    const tr = ocMk("tr"); tr.dataset.scenario = x.scenarioId;
    const rb = ocMk("td", x.robot?.gap ? "oc-bad" : "oc-ok", x.robot ? `${x.robot.modelId} ${x.robot.k}/${x.robot.n} — ${x.robot.gap ? `gap: ${x.robot.why}` : x.robot.why}` : "not run");
    const pt = x.people.learner ? `${x.people.why}${x.people.learner.todo.length ? ` — to practise: ${x.people.learner.todo.join(", ")}` : ""}` : x.people.gap ? `gap: ${x.people.why}` : `${x.people.why}: ${x.people.stations.join(", ")}`;
    const pe = ocMk("td", x.people.gap === true ? "oc-bad" : x.people.gap === false ? "oc-ok" : null, pt);
    tr.append(ocMk("td", null, x.scenarioId), rb, pe); st.appendChild(tr);
  }
  body.appendChild(st);
  }
  renderBody();
  el.appendChild(box);
  return { el: box, get chain() { return chain; }, get need() { return need; }, get record() { return record; }, records: recs, select(declId) { const r = recs.find((x) => x.runs.some((y) => y.declId === declId)); if (r && r !== record) { record = r; renderBody(); const ps = box.querySelector("#oc-protocol"); if (ps) ps.value = String(recs.indexOf(r)); } sel.value = declId; sel.dispatchEvent(new Event("change")); } };
}

/** The persistent world's view. `loop` is ocWorldLoop(...). */
export function ocMountWorld(el, { loop = null } = {}) {
  if (!el || typeof document === "undefined" || !loop) return null;
  const box = ocMk("section", "oc-panel"); box.id = "oc-world"; box.setAttribute("aria-label", "Robots at work: the persistent simulated robot world");
  ocStyleOnce(box);
  box.appendChild(ocMk("h3", null, "Robots at work (simulated)"));
  box.appendChild(ocMk("p", "oc-note", "The six robot sites keep running the hive's jobs with the model the Omega Claw promoted for each task, one simulated minute a second. It pauses while this tab is hidden and catches up (at most one simulated day) when you come back. Deterministic for its seed; nothing is uploaded; the governor checks every step and the physical path stays disabled."));
  const row = ocMk("div", "oc-row");
  const clock = ocMk("span", "oc-stat"); clock.dataset.oc = "clock";
  const btn = ocMk("button", null, "Pause"); btn.type = "button"; btn.dataset.oc = "pause"; btn.setAttribute("aria-pressed", "false");
  row.append(clock, btn); box.appendChild(row);
  const sum = ocMk("div", "oc-sum"); sum.dataset.oc = "world"; box.appendChild(sum);
  const sites = ocMk("div", "oc-sites"); sites.dataset.oc = "sites"; box.appendChild(sites);
  let userPaused = false;
  btn.addEventListener("click", () => { userPaused = !userPaused; if (userPaused) loop.pause(); else loop.resume(); render(); });
  function render() {
    const s = loop.world.stats();
    const hh = String(Math.floor(s.minute / 60)).padStart(2, "0"), mm = String(s.minute % 60).padStart(2, "0");
    const state = userPaused ? "paused" : loop.paused() ? "paused (tab hidden)" : "running";
    clock.textContent = `Day ${s.day + 1} · ${hh}:${mm} · ${state}`; clock.dataset.state = state;
    btn.textContent = userPaused ? "Resume" : "Pause"; btn.setAttribute("aria-pressed", String(userPaused));
    sum.textContent = "";
    for (const [t, key] of [[`${s.minutes.toLocaleString("en-US")} simulated minutes`, "minutes"], [`${s.completed} jobs completed`, "completed"], [`governor ${s.stepsMonitored.toLocaleString("en-US")}/${s.steps.toLocaleString("en-US")} steps`, "governor"], [`physical dispatches ${s.physicalDispatched}`, "physical"], [`${s.waitingSupervisor} waiting for a supervisor (physical path disabled)`, "waiting"], [loop.catchUp ? `caught up ${loop.catchUp} min on arrival` : "no catch-up", "catchup"]]) { const x = ocMk("span", "oc-stat", t); x.dataset.oc = key; sum.appendChild(x); }
    sites.textContent = "";
    const modelFor = (rig) => { const sc = { amr: "rb-amr-fleet-routing", gantry: "rb-amr-fleet-routing", cobot: "rb-cobot-zone-setup", cell: "rb-cell-entry" }[rig]; return s.promoted[sc] ?? "scripted"; };
    for (const x of s.sites) { const c = ocMk("div", "oc-site"); c.dataset.site = x.siteId; c.append(ocMk("div", "oc-name", x.name.replace(/ \(procedural\)$/, "")), ocMk("div", "oc-role", `${x.rig} · ${x.completed} done · ${x.busy ? `${x.busy} at work` : "idle"} · model ${modelFor(x.rig)}`)); sites.appendChild(c); }
  }
  loop.onTick(render);
  try { document.addEventListener("visibilitychange", render); } catch (_) { /* headless */ }
  render();
  el.appendChild(box);
  return { el: box, render, loop };
}
